$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-15pm-p3-compact.mjs'
try{[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},7800);try{
const t=(await(await fetch('http://127.0.0.1:17447/json/list')).json()).find(x=>x.id==='FCD1272A7DC4E4537390D862FE735F52');if(!t)throw Error('tab_missing');
const w=new WebSocket(t.webSocketDebuggerUrl);w.addEventListener('open',()=>w.send(JSON.stringify({id:99,method:'Runtime.evaluate',params:{expression:"(()=>({url:location.href,count:document.querySelectorAll('[data-marker=item]').length,rows:Array.from(document.querySelectorAll('[data-marker=item]')).slice(0,8).map(x=>[x.getAttribute('data-item-id'),x.querySelector('[itemprop=name]')?.textContent?.trim(),x.querySelector('[itemprop=price]')?.getAttribute('content'),x.querySelector('[data-marker=item-title]')?.getAttribute('href')?.split('?')[0]] )}))()",returnByValue:true}})),{once:true});
