w.addEventListener('error',()=>{console.log('{"error":"ws"}');process.exit(0)},{once:true});
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,140)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
